import{_,o as t,c as a,a4 as s}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"精准培训补短板 守护田间“冷链安全”——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"精准培训补短板 守护田间“冷链安全”——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24","date":"2026-07-24T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202607/t20260724_6486173.htm","summary":"近日,全省农产品产地冷库安全使用专题培训班在运城市盐湖区开班。各市、县(区)农业农村部门分管领导及业务负责人参训。本次培训紧扣安全生产月工作要求,聚焦农产品产地冷库管理制度不完善、操作不规范、设施老化、安全意识薄弱等突出问题,以“明职责、查隐患、教方法、压责任”为核心,通过理论授课、互动答疑、现场实操相结合的方式开展靶向培训,精准补齐基层监管工作短板。\\n...\\n","contentHash":"8e75f7ee7bf020bb711a99b17f0114cb","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-07-24-精准培训补短板-守护田间-冷链安全-全省农业农村系统开展产地冷库安全使用专题培训.md","filePath":"policies/2026-07-24-精准培训补短板-守护田间-冷链安全-全省农业农村系统开展产地冷库安全使用专题培训.md"}'),r={name:"policies/2026-07-24-精准培训补短板-守护田间-冷链安全-全省农业农村系统开展产地冷库安全使用专题培训.md"};function o(p,e,n,l,c,i){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="精准培训补短板-守护田间-冷链安全-——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24" tabindex="-1">精准培训补短板 守护田间“冷链安全”——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24 <a class="header-anchor" href="#精准培训补短板-守护田间-冷链安全-——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24" aria-label="Permalink to &quot;精准培训补短板 守护田间“冷链安全”——全省农业农村系统开展产地冷库安全使用专题培训2026-07-24&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202607/t20260724_6486173.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-07-24 摘要: 近日,全省农产品产地冷库安全使用专题培训班在运城市盐湖区开班。各市、县(区)农业农村部门分管领导及业务负责人参训。本次培训紧扣安全生产月工作要求,聚焦农产品产地冷库管理制度不完善、操作不规范、设施老化、安全意识薄弱等突出问题,以“明职责、查隐患、教方法、压责任”为核心,通过理论授课、互动答疑、现场实操相结合的方式开展靶向培训,精准补齐基层监管工作短板。 ...</p></blockquote><p>近日,全省农产品产地冷库安全使用专题培训班在运城市盐湖区开班。各市、县(区)农业农村部门分管领导及业务负责人参训。本次培训紧扣安全生产月工作要求,聚焦农产品产地冷库管理制度不完善、操作不规范、设施老化、安全意识薄弱等突出问题,以“明职责、查隐患、教方法、压责任”为核心,通过理论授课、互动答疑、现场实操相结合的方式开展靶向培训,精准补齐基层监管工作短板。</p><p>开班仪式上,省农业农村厅副厅长高耀东作动员讲话。会议强调,产地冷库是保障农产品仓储保鲜、助农增收的重要基础设施,安全运行事关群众生命财产安全和农业发展大局。结合典型安全事故案例,深入剖析冷库管护、设备运维、规范操作等方面的突出问题,并明确四项工作重点:一是厘清监管职责,抓实冷库使用环节精准监管;二是开展全域摸底排查,动态更新冷库台账,摸清底数实情;三是严格对照《农产品产地冷库使用安全十必看》排查隐患,落实整改闭环管理;四是压实监管和主体双重责任,常态化开展安全宣教与巡查,通过技术升级提升老旧冷库安全水平,坚决杜绝麻痹松懈思想,筑牢农业安全生产防线。</p><p>培训期间,行业专家围绕冷库安全管理规范、信息填报标准等内容开展专项授课,逐条解读产地冷库使用安全“十必看”实操要点,将专业规范转化为基层可落地、易操作的工作方法,并通过现场答疑交流,有效破解一线监管难点堵点。</p><p>全体参训人员前往运城博萌亮农业发展有限公司和山西奇雄农业发展有限公司开展现场教学,由山西农业大学专业教师分组带队、循环轮训。通过示范讲解、互动研讨、实操演练等方式,详细拆解冷库安全检查流程、监管重点和实操规范,多轮次沉浸式实训确保参训人员学深悟透、熟练掌握实操技能。</p><p>参训人员普遍反映,本次培训贴合基层实际、内容务实管用,有效补齐了业务短板、理清了监管思路,大幅提升了冷库安全管理和隐患排查实操能力。下一步,全省农业农村系统将转化落实本次培训成果,全面开展产地冷库使用安全隐患专项大排查,从严压实安全责任,常态化整治风险隐患,全力守护群众生命财产安全,护航全省农业高质量发展。</p><p><a href="https://scs.moa.gov.cn/gzdt/202607/t20260724_6486173.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',8)])])}const m=_(r,[["render",o]]);export{f as __pageData,m as default};
